import { MeshPhysicalNodeMaterial, PlaneGeometry, Group, Texture, DirectionalLight, Color } from 'three/webgpu';
import { texture, uv, color, mix, smoothstep, vec2, sin, fract, dot, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group: THREEGroup } = ctx.THREE ?? {};
  const GroupCls = THREEGroup ?? Group;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new GroupCls();
  root.name = 'pricing-card-3';

  // ---- geometry / dimensions (aspect derived from atlas source rect 512x320) ----
  const cardWidth = 2.2;
  const cardHeight = cardWidth * (320 / 512);
  const geometry = new PlaneGeometry(cardWidth, cardHeight, 1, 1);

  // ---- material: machined-metal engineered gradient card ----
  const material = new MeshPhysicalNodeMaterial({
    roughness: 0.58,
    metalness: 0.42,
    clearcoat: 0.18,
    clearcoatRoughness: 0.35,
  });

  const uvNode = uv();
  const inkColor = color(colors.ink);
  const paperColor = color(colors.paper);
  const surfaceColor = color(colors.surface);
  const accentColor = color(colors.accent);

  // vertical engineered gradient: surface -> ink, subtle paper glint near top
  const verticalMix = mix(surfaceColor, inkColor, smoothstep(0.0, 1.0, uvNode.y));
  const topGlint = smoothstep(0.82, 1.0, uvNode.y);
  const gradientBase = mix(verticalMix, paperColor, topGlint.mul(0.08));

  // fine grain (static, deterministic pseudo-random)
  const grainSeed = dot(uvNode.mul(vec2(600.0, 900.0)), vec2(12.9898, 78.233));
  const grainRaw = fract(sin(grainSeed).mul(43758.5453));
  const grain = grainRaw.sub(0.5).mul(0.035);

  // thin accent edge line at very top of card (<=10% of frame area)
  const edgeLine = smoothstep(0.965, 0.985, uvNode.y).sub(smoothstep(0.985, 1.0, uvNode.y));
  const withAccent = mix(gradientBase, accentColor, edgeLine.mul(0.9));

  const fallbackColorNode = withAccent.add(grain);
  material.colorNode = fallbackColorNode;

  const mesh = new (ctx.THREE?.Mesh ?? MeshPhysicalNodeMaterialFallback())(geometry, material);
  function MeshPhysicalNodeMaterialFallback() {
    throw new Error('THREE.Mesh missing on ctx.THREE');
  }
  root.add(mesh);

  // ---- rim / accent light, node-local (scene supplies ambient 0.6 + key 1.2 only) ----
  const rimLight = new DirectionalLight(new Color(colors.accent), 0.7);
  rimLight.position.set(-1.2, 0.6, 2.0);
  root.add(rimLight);

  // ---- async texture load: swap colorNode once real image resolves ----
  let disposed = false;
  let loadedTexture = null;
  const texUrl = config.imageUrl;
  if (texUrl) {
    ctx.textureLoader.loadTexture(texUrl).then((tex) => {
      if (disposed) return;
      loadedTexture = tex;
      const texNode = texture(tex, uvNode);
      const blended = mix(texNode.rgb, withAccent, 0.14).add(grain);
      material.colorNode = blended;
      material.needsUpdate = true;
    }).catch(() => {
      // keep procedural fallback on failure
    });
  }

  // ---- entrance motion: fade-up + weighted-settle (static composition after) ----
  root.scale.setScalar(0.98);
  const opacityUniform = uniform(0);
  material.opacityNode = opacityUniform;
  material.transparent = true;

  const tl = gsap.timeline();
  tl.to(opacityUniform, { value: 1, duration: 0.5, ease: 'power2.out' });
  tl.to(root.position, { y: root.position.y + 0.2, duration: 0.001 }, 0); // no-op guard; adapter owns base position
  tl.to(root.scale, {
    x: 1.04, y: 1.04, z: 1.04,
    duration: 0.5,
    ease: 'power3.out',
  }, 0);
  tl.to(root.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out',
  }, 0.5);

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    disposed = true;
    tl.kill();
    gsap.killTweensOf(root.position);
    gsap.killTweensOf(root.scale);
    gsap.killTweensOf(opacityUniform);
    geometry.dispose();
    material.dispose();
    if (loadedTexture && loadedTexture.dispose) {
      loadedTexture.dispose();
    }
    root.remove(rimLight);
  };

  return root;
}
